import 'dart:convert';
import 'dart:io';

/// Run from apps/mobile: dart tool/generate_mobile_flags.dart.
void main() {
  final source = File('../../config/feature-flags.json');
  if (!source.existsSync()) {
    stderr.writeln(
      'config/feature-flags.json is absent; keeping committed keys.',
    );
    return;
  }
  final entries = jsonDecode(source.readAsStringSync()) as List<dynamic>;
  final keys = entries.map((dynamic row) => (row as Map)['key'] as String);
  final output = StringBuffer(
    '// Generated by tool/generate_mobile_flags.dart. Do not edit.\n'
    'enum MobileFlag {\n',
  );
  for (final key in keys) {
    if (!RegExp(r'^[a-z][a-z0-9_]*$').hasMatch(key)) {
      throw FormatException('Invalid flag key: $key');
    }
    final words = key.split('_');
    final name =
        words.first +
        words.skip(1).map((w) => w[0].toUpperCase() + w.substring(1)).join();
    output.writeln("  $name('$key'),");
  }
  output.write(
    '  ;\n\n  const MobileFlag(this.key);\n'
    '  final String key;\n}\n',
  );
  File('lib/core/feature_flags/mobile_flag.dart').writeAsStringSync('$output');
}
